const i = $input.first().json || {};
let filtros = {};
try { const f = typeof i.filtros === 'string' && i.filtros.trim() ? JSON.parse(i.filtros) : (i.filtros || {}); if (f && typeof f === 'object' && !Array.isArray(f)) { for (const k of ['categoria', 'cores', 'tamanho', 'gramatura']) { if (f[k] !== undefined && f[k] !== null && String(f[k]).trim() !== '') filtros[k] = f[k]; } } } catch (e) { filtros = {}; }
const termo = String(i.termo || '').trim().slice(0, 200);
const qtd = Number(i.quantidade);
return [{ json: { valido: termo.length >= 2, body: { p_termo: termo, p_quantidade: Number.isFinite(qtd) && qtd > 0 ? Math.round(qtd) : null, p_filtros: filtros } } }];

const orig = $('Preparar busca').first().json.body || {};
const stop = new Set(['de','da','do','das','dos','para','pra','com','uma','uns','umas','quero','queria','preciso','gostaria','orcamento','fazer','tem','voce','voces','por','favor','quanto','custa','valor','preco','frente','verso','mil','unidade','unidades']);
const norm = String(orig.p_termo || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const palavras = norm.split(/[^a-z0-9]+/).filter((w) => w.length >= 3 && !stop.has(w) && !/^[0-9]+$/.test(w));
const termo = (palavras.slice(0, 3).join(' ') || String(orig.p_termo || '')).slice(0, 200);
return [{ json: { body: { p_termo: termo, p_quantidade: orig.p_quantidade ?? null, p_filtros: {} }, erro_primeira_busca: String(($input.first().json.error && ($input.first().json.error.description || $input.first().json.error.message)) || $input.first().json.message || '').slice(0, 200) } }];

const r = $input.first().json || {};
let viaReserva = false;
try { viaReserva = $('Buscar reserva').isExecuted === true; } catch (e) { viaReserva = false; }
if (r.error || r.message || r.ok === false) {
  const det = String((r.error && (r.error.description || r.error.message)) || r.message || r.erro || 'falha desconhecida').slice(0, 200);
  return [{ json: { opcoes: [], erro: 'indisponivel', erro_detalhe: det, orientacao: 'A busca falhou duas vezes. Não invente produto nem valor e não mande link. Mantenha a conversa: diga que vai confirmar esse item com a equipe, peça para o cliente aguardar um instante e use chamar_dono (gravidade alta). Não repita perguntas já respondidas.' } }];
}
const opcoes = (Array.isArray(r.opcoes) ? r.opcoes : []).slice(0, 5).map((o, idx) => ({ numero: idx + 1, sku: String(o.sku || ''), descricao: String(o.descricao_curta || o.descricao || '').slice(0, 140), em_palavras: o.em_palavras ? String(o.em_palavras).slice(0, 160) : undefined, quantidade: o.quantidade, preco: o.preco, vendavel: o.vendavel !== false, quantidade_exata: o.quantidade_exata === true }));
const saida = { opcoes, regra_descricao: 'Descreva a impressão, o tamanho e o papel de cada opção SOMENTE com o campo em_palavras (e a descricao) daquela opção. Nunca use a descrição de outra opção nem invente se é frente e verso. Ao resumir o pedido, use a opção exata que o cliente escolheu.' };
if (viaReserva) saida.busca_simplificada = 'A busca detalhada falhou e estas são as opções mais próximas pelas palavras-chave. Confirme com o cliente o que ele precisa (tamanho, papel, cores) antes de cotar.';
if (Array.isArray(r.acabamentos_disponiveis) && r.acabamentos_disponiveis.length > 0) {
  saida.acabamentos_disponiveis = r.acabamentos_disponiveis.map((a) => ({
    nome: String(a.nome || ''),
    tipo: String(a.tipo || 'padrao'),
    dias_adicionais: Number(a.dias_adicionais || 0),
    custo_adicional: Number(a.custo_adicional || 0),
    obrigatorio_escolher: a.obrigatorio_escolher === true,
    pergunta: a.pergunta ? String(a.pergunta).slice(0, 200) : undefined
  }));
}
if (r.pergunta_qualificacao) saida.pergunta_qualificacao = String(r.pergunta_qualificacao).slice(0, 200);
if (r.oferecer_mais_proxima === true) saida.oferecer_mais_proxima = 'A quantidade pedida não existe como opção. Ofereça a opção mais próxima da lista.';
if (!opcoes.length) saida.orientacao = 'Nada encontrado com esses termos. Tente de novo uma vez com palavras mais simples (por exemplo só o produto). Se continuar vazio, escolha o item mais próximo do catálogo e confirme com o cliente; só se não houver nada parecido diga que vai confirmar e use chamar_dono (gravidade alta). Não prometa o item sem SKU.';
return [{ json: saida }];
